    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        offsets = Counter((v - 1 - c) % 9 for c, v in enumerate(row) if v != 0)
        offset = offsets.most_common(1)[0][0]
        for c, v in enumerate(row):
            if v == 0:
                out[r][c] = (offset + c) % 9 + 1
