    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        offsets = {}
        for c, v in enumerate(row):
            if v:
                k = (v - c - 1) % 9
                offsets[k] = offsets.get(k, 0) + 1
        k = max(offsets, key=offsets.get)
